"""The 5E3 with a bench's mods (config/circuits/fender_5e3_mods.yaml, GENERATED by
scripts/make_fender_5e3_mods.py from the stock file): current with its generator, checked at
every switch position, its jumpered inputs wired, and each mod moving the operating point the
way the physics says (at its defaults, the stock amp's).
"""

import importlib.util

import numpy as np
import pytest

from varimu import preflight
from varimu.circuit import builder, spec
from varimu.config import CONFIG_DIR, REPO_ROOT

STOCK = CONFIG_DIR / "circuits" / "fender_5e3.yaml"
MODS = CONFIG_DIR / "circuits" / "fender_5e3_mods.yaml"


def _generator():
    path = REPO_ROOT / "scripts" / "make_fender_5e3_mods.py"
    s = importlib.util.spec_from_file_location("make_fender_5e3_mods", path)
    m = importlib.util.module_from_spec(s)
    s.loader.exec_module(m)
    return m


@pytest.fixture(scope="module")
def mods():
    return spec.load_circuit(MODS)


def test_generated_file_is_current():
    assert MODS.read_text(encoding="utf-8") == _generator().derive()


def test_preflight_passes_at_every_switch_position(mods):
    assert preflight.check_circuit(mods) == []
    # input_jack 5 x rectifier 3 x v1_tube 2
    assert len(preflight.switch_configs(mods)) == 30


def test_jumpered_inputs_feed_both_grids(mods):
    from varimu.circuit.ir import Resistor

    els = [
        e
        for e in builder.build_ir(mods, spec.resolve(mods, {"input_jack": 5})).elements()
        if isinstance(e, Resistor) and e.name.startswith(("RIN1", "RGA", "RGB", "RJ"))
    ]
    nodes = sorted({n for e in els for n in (e.a, e.b)} - {"0", "in"})
    ix = {n: i for i, n in enumerate(nodes)}
    g, rhs = np.zeros((len(nodes), len(nodes))), np.zeros(len(nodes))
    for e in els:
        for p, q in ((e.a, e.b), (e.b, e.a)):
            if p in ix:
                g[ix[p], ix[p]] += 1 / e.r_ohm
                if q in ix:
                    g[ix[p], ix[q]] -= 1 / e.r_ohm
                elif q == "in":
                    rhs[ix[p]] += 1 / e.r_ohm
    v = np.linalg.solve(g, rhs)
    # The bright grid from the jack, the normal one through the patch cable; the cable
    # loads the bright side with the normal channel's 1 MEG (68K + 68K into it: 0.94).
    print(f"jumpered: g1b {v[ix['g1b']]:.3f}, g1n {v[ix['g1n']]:.3f} of the jack")
    assert v[ix["g1b"]] == pytest.approx(1.0 - 68e3 / (2 * 68e3 + 1e6), abs=0.02)
    assert 0.85 < v[ix["g1n"]] < v[ix["g1b"]]


def _idle(circuit, **values):
    from varimu.sim import fast
    from varimu.sim.io import TransientSettings

    st = TransientSettings.from_sim_settings(engine="circuitsim")
    x = np.zeros(int(0.3 * st.sample_rate))
    ir = builder.build(circuit, spec.resolve(circuit, values)).ir
    v = fast.run_transient(ir, x, settings=st).vectors
    n = int(0.1 * st.sample_rate)
    return {k[2:-1]: float(np.mean(a[-n:])) for k, a in v.items() if k.startswith("v(")}


def test_each_mod_moves_the_operating_point(mods):
    pytest.importorskip("circuitsim", reason="needs `uv sync --extra fast`")
    stock = _idle(spec.load_circuit(STOCK))
    base = _idle(mods)
    # At its defaults the stock amp (its cathodes heated at the rated mains: the fitted
    # models exactly, warm).
    for node in ("b1", "b2", "b3", "k6", "p2", "k1"):
        assert base[node] == pytest.approx(stock[node], rel=1e-3), node
    # RECTIFIER: the 5Y3GT drops most, silicon nothing.
    gz34, si = _idle(mods, rectifier=2)["b1"], _idle(mods, rectifier=3)["b1"]
    print(f"B+1: 5Y3GT {base['b1']:.1f} V, GZ34 {gz34:.1f} V, silicon {si:.1f} V")
    assert base["b1"] < gz34 < si
    # VARIAC: B+ down nearly in proportion at 90 V.
    low = _idle(mods, mains_v_rms=90.0)
    print(f"VARIAC 90 V: B+1 {low['b1']:.1f} V (at 120 V {base['b1']:.1f})")
    assert 0.65 < low["b1"] / base["b1"] < 0.82
    # BIAS: a smaller cathode resistor runs the 6V6GTs hotter (more current, less bias).
    hot = _idle(mods, r_cathode6_ohm=150.0)
    i_hot, i_base = hot["k6"] / 150.0, base["k6"] / 250.0
    print(f"6V6GT pair: {1e3 * i_base:.1f} mA at 250 ohm, {1e3 * i_hot:.1f} mA at 150 ohm")
    assert hot["k6"] < base["k6"] and i_hot > i_base
    # V1: the 12AX7 idles (its higher mu draws less current at the shared 820 ohm).
    ax = _idle(mods, v1_tube=2)
    print(f"V1 cathode: 12AY7 {base['k1']:.2f} V, 12AX7 {ax['k1']:.2f} V")
    assert 0.3 < ax["k1"] < base["k1"]
